// Water logistics runs six times slower than the guard clock for playable tank autonomy.
export const waterMinutes=guardMinutes=>guardMinutes/6;
// Une seule famille : la lance à débit variable. Le débit et le jet se règlent par binôme.
export const NOZZLES={lance:{label:'Lance',flow:250,max:2}};
// Anciennes lances (sauvegardes, appels historiques) converties en débit sur la lance unique.
export const LEGACY_NOZZLES={ldt:150,small:250,large:500};
export const JETS={droit:{label:'Droit',hint:'Porte loin · efficacité constante'},diffuse:{label:'Diffusé',hint:'Éteint mieux de près (≤ 10 m), moins bien de loin'},protection:{label:'Protection',hint:'Rideau d’eau qui protège le binôme · attaque réduite'}};
export const LANCE_REACH=45;
export const LANCE_RELOCATE_MINUTES=2;
export const lanceFlows=e=>e.firstAid?[110,250]:e.kind==='CCF'?[150,250]:[150,250,350,500];
export const defaultLanceFlow=e=>e.firstAid?110:250;
export const lanceLabel=(e,h)=>e.firstAid&&(h?.flow??defaultLanceFlow(e))===110?'Lance diphasique':'Lance';
export const nozzleFlow=(e,key='lance')=>LEGACY_NOZZLES[key]&&!(e.firstAid&&key==='ldt')?LEGACY_NOZZLES[key]:defaultLanceFlow(e);
export const nozzleLabel=(e,key='lance')=>lanceLabel(e);
export const pumpCapacity=e=>e.kind==='FPT'?(e.lightPump?1000:2000):e.kind==='CCF'?1000:2000;
export const TANKS={FPT:3000,CCF:4000};
const newHose=(e,index)=>({key:'lance',index,progress:0,flow:defaultLanceFlow(e),jet:'droit',open:true,position:null,from:null,relocate:0});
export function initWater(e){if(e.kind==='CCF')e.size=4;e.capacity=e.tankCapacity??TANKS[e.kind]??0;e.water=e.capacity;e.nozzles={lance:0};e.hydrant=null;e.flow=0;e.attackFactor=1;e.hoses=Array.from({length:NOZZLES.lance.max},(_,index)=>newHose(e,index));e.supplyProgress=0;e.supplyHydrant=null;e.supplyAnchor=null;e.supplyRoute=null;e.supplyOrigin=null;e.supplyLength=0;e.supplyDuration=14;e.supplyPackDuration=10.5;}
// Convertit une ancienne sauvegarde (LDT / petite / grosse lance) vers la lance unique.
export function migrateLances(e){if(!e.capacity&&!e.hoses)return;const old=e.nozzles||{},legacy=Object.keys(old).some(k=>k!=='lance')||(e.hoses||[]).some(h=>h.key!=='lance');if(!legacy&&e.hoses?.length===NOZZLES.lance.max&&e.hoses.every(h=>h.flow))return;const flows=lanceFlows(e),wanted=[];for(const key of['large','small','ldt'])for(let n=0;n<(old[key]||0);n++)wanted.push(key);const previous=(e.hoses||[]).filter(h=>h.key==='lance');const total=Math.min(NOZZLES.lance.max,legacy?wanted.length:(old.lance||0));e.hoses=Array.from({length:NOZZLES.lance.max},(_,index)=>{const h=Object.assign(newHose(e,index),previous[index]||{}),key=wanted[index];if(key){const flow=e.firstAid&&key==='ldt'?110:LEGACY_NOZZLES[key];h.flow=flows.includes(flow)?flow:flows.filter(f=>f<=flow).at(-1)??flows[0];const prior=(e.hoses||[]).find(o=>o.key===key&&o.index===wanted.slice(0,index).filter(k=>k===key).length);h.progress=prior?.progress??0;}h.key='lance';h.index=index;if(!flows.includes(h.flow))h.flow=defaultLanceFlow(e);return h;});e.nozzles={lance:total};}
export function nozzleLimit(e){const supply=!e.longSupplyProvider&&(e.hydrant?e.supplyProgress<1:e.supplyProgress>0);const commandCrew=e.firstAid||['FPT','CCF'].includes(e.kind)?2:0,limit=e.firstAid?2:e.kind==='CCF'?2:e.kind==='FPT'?(e.lightPump?1:2):NOZZLES.lance.max;return Math.min(limit,Math.max(0,Math.floor(((e.crew??e.size??6)-commandCrew-(e.perimeterCrew||0)-(e.buildingCrew||0)-(e.ventilationCrew||0)-(e.rescueCrew||0)-(e.extricationTask!=null?2:0)-(supply?2:0))/(e.kind==='CCF'?1:2))));}
export function nozzleCount(e){return e.nozzles?.lance||0;}
const resolveKey=(e,key)=>key==='lance'?{ok:true}:LEGACY_NOZZLES[key]!=null?(()=>{const flow=e.firstAid&&key==='ldt'?110:LEGACY_NOZZLES[key];return{ok:lanceFlows(e).includes(flow),flow};})():{ok:false};
export function nozzleAllowed(e,key,count){const r=resolveKey(e,key);if(!r.ok||!Number.isInteger(count)||count<0||count>NOZZLES.lance.max)return false;return count<=nozzleCount(e)||count<=nozzleLimit(e);}
export function staffedHoses(e){return (e.hoses||[]).filter(h=>h.index<nozzleCount(e)).slice(0,nozzleLimit(e));}
// Établit ou replie des lances. Un ancien nom de lance fixe le débit des nouvelles lances.
export function setNozzle(e,key,count){if(e.noria||e.tacticalPlacement==='Aspiration au lac'&&count>0||e.kind==='CCGC'||e.status!=='scene'||!e.capacity)return false;const r=resolveKey(e,key);if(!r.ok||!Number.isFinite(count)||!nozzleAllowed(e,key,count))return false;if(!e.hoses||e.nozzles?.lance==null)migrateLances(e);const before=nozzleCount(e),next=Math.max(0,Math.min(NOZZLES.lance.max,Math.floor(count)));for(const h of e.hoses){if(h.index>=before&&h.index<next){if(h.progress<=0){h.position=null;h.from=null;h.relocate=0;h.jet='droit';h.open=true;}if(r.flow)h.flow=r.flow;}}e.nozzles={lance:next};return true;}
export function lanceAt(e,index){const h=e.hoses?.[index];return h&&index<nozzleCount(e)?h:null;}
export function setLanceFlow(e,index,flow){const h=lanceAt(e,index);if(!h||!lanceFlows(e).includes(flow))return false;h.flow=flow;return true;}
export function setLanceJet(e,index,jet){const h=lanceAt(e,index);if(!h||!JETS[jet])return false;h.jet=jet;return true;}
export function setLanceOpen(e,index,open){const h=lanceAt(e,index);if(!h)return false;h.open=!!open;return true;}
const enginePoint=e=>e.model?.position?[e.model.position.x,e.model.position.z]:null;
const lancePoint=(e,h)=>h.position||enginePoint(e);
export function lanceMoveError(e,index,point){const h=lanceAt(e,index);if(!h)return 'Aucune lance établie pour ce binôme.';if(h.progress<1)return 'Attendre la fin de l’établissement.';if(!Array.isArray(point)||!point.every(Number.isFinite))return 'Position invalide.';const base=enginePoint(e);if(base&&Math.hypot(point[0]-base[0],point[1]-base[1])>LANCE_REACH)return `Trop loin de l’engin · ${LANCE_REACH} m de tuyaux maximum.`;return null;}
export function setLancePosition(e,index,point){if(lanceMoveError(e,index,point))return false;const h=lanceAt(e,index);h.from=h.position?h.position.slice():null;h.position=[point[0],point[1]];h.relocate=1;return true;}
export function jetFactor(e,h){if(h.jet==='protection')return .5;if(h.jet!=='diffuse')return 1;const at=lancePoint(e,h),target=e.hoseTarget;if(!at||!target)return 1;return Math.hypot(at[0]-target[0],at[1]-target[1])<=10?1.2:.8;}
export const hoseFlowing=(e,h)=>h.progress>=1&&h.open!==false&&!(h.relocate>0);
export function tickWater(e,minutes){const hoses=staffedHoses(e).filter(h=>hoseFlowing(e,h)),ground=hoses.reduce((sum,h)=>sum+(h.flow||defaultLanceFlow(e)),0),weighted=hoses.reduce((sum,h)=>sum+(h.flow||defaultLanceFlow(e))*jetFactor(e,h),0),external=e.aerialDemand||0,requested=ground+external;const incoming=e.hydrant&&e.supplyProgress>=1?1000:0;const available=e.water+incoming*minutes,total=minutes>0?Math.min(requested,pumpCapacity(e),available/minutes):0,factor=requested?total/requested:0;e.flow=ground*factor;e.attackFactor=ground?weighted/ground:1;e.externalFlow=external*factor;e.pumpFlow=total;e.pumpLimited=requested>pumpCapacity(e)&&total>=pumpCapacity(e);e.water=Math.max(0,Math.min(e.capacity,available-total*minutes));return e.flow;}
export function stow(e){e.foamOn=false;e.foamFlow=0;e.nozzles={lance:0};e.hydrant=null;e.flow=0;e.attackFactor=1;e.externalFlow=0;e.pumpFlow=0;e.pumpLimited=false;e.aerialDemand=0;}

const layMinutes=e=>e.firstAid?8.4:14;
export function tickEquipment(e,minutes){if(!e.hoses)return;if(e.hydrant&&e.supplyHydrant!==e.hydrant){e.supplyHydrant=e.hydrant;e.supplyAnchor=e.hydrant.position.clone();e.supplyRoute=null;e.supplyOrigin=null;e.supplyDuration=14;e.supplyPackDuration=10.5;}if(!e.hydrant&&e.supplyProgress===0){e.supplyHydrant=null;e.supplyAnchor=null;e.supplyRoute=null;e.supplyOrigin=null;e.supplyLength=0;}const staffed=staffedHoses(e);for(const h of e.hoses){const wanted=h.index<nozzleCount(e);if(wanted&&!staffed.includes(h))continue;h.progress=Math.max(0,Math.min(1,h.progress+minutes*(wanted?1/layMinutes(e):-1/10.5)));if(h.relocate>0)h.relocate=Math.max(0,h.relocate-minutes/LANCE_RELOCATE_MINUTES);if(!wanted&&h.progress<=0){h.position=null;h.from=null;h.relocate=0;}}const supplyMinutes=Math.max(0,minutes-(e.hydrant?Math.min(minutes,e.supplyDeployWait||0):0));e.supplyDeployWait=Math.max(0,(e.supplyDeployWait||0)-minutes);e.supplyProgress=Math.max(0,Math.min(1,(e.supplyProgress||0)+supplyMinutes*(e.hydrant?1/(e.supplyDuration||14):-1/(e.supplyPackDuration||10.5))));}
export function equipmentBusy(e){return e.hoses?.some(h=>h.index<nozzleCount(e)?h.progress<1||h.relocate>0:h.progress>0)||!!(e.hydrant?e.supplyProgress<1:e.supplyProgress>0);}
export function equipmentStatus(e){const laying=e.hoses?.some(h=>h.index<nozzleCount(e)&&h.progress<1),packing=e.hoses?.some(h=>h.index>=nozzleCount(e)&&h.progress>0),moving=e.hoses?.some(h=>h.index<nozzleCount(e)&&h.relocate>0);return laying?'Établissement des tuyaux et lances':packing?'Rangement des tuyaux et lances':moving?'Binôme en déplacement':e.hydrant&&e.supplyProgress<1?(e.hydrant.userData?.supplyKind==='lake'?'Installation des aspiraux':'Raccordement au poteau'):!e.hydrant&&e.supplyProgress>0?'Rangement de l’alimentation':'';}
